cd /tmp/vally-eval-trial-LJMJNe && mkdir -p tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount && cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public sealed class LoyaltyDiscountAcceptanceTests
{
    [Theory]
    // Returning customer in the Bronze tier is charged the Bronze price
    [InlineData(LoyaltyTier.Bronze, 10000, 9500)]
    public void Returning_customer_is_charged_the_price_for_their_loyalty_tier(
        LoyaltyTier loyaltyTier, int subtotalCents, int expectedTotalCents)
    {
        var useCase = new CalculateLoyaltyDiscount();

        var quote = useCase.Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, loyaltyTier));

        Assert.Equal(expectedTotalCents, quote.TotalCents);
    }
}
EOF
git rev-parse HEAD; ls; dotnet build tests/CheckoutPricing.UnitTest 2>&1 | tail -3
D=.copilot-tracking/skraft-plans/pricing/evidence/2026-10-17/discount; mkdir -p $D
dotnet test tests/CheckoutPricing.UnitTest --filter "FullyQualifiedName~LoyaltyDiscountAcceptanceTests" > $D/acceptance-red.stdout 2>&1; echo $? > $D/acceptance-red.exit; git rev-parse HEAD > $D/acceptance-red.rev; cat $D/acceptance-red.exit; grep -E "Assert|Expected|Actual|Failed|error" $D/acceptance-red.stdout | head

